const url = tabProperties.url
  ? extension.baseURI.resolve(tabProperties.url)
  : null;

const protocol = url && new URL(url).protocol;
if (!protocol || !["https:", "http:", "moz-extension:"].includes(protocol)) {
  throw new Error(url ? `Invalid URL: ${url}` : `Missing URL`);
}

const linkHandler = getMessageManagerGroup(tabProperties?.linkHandler);

return {
  url,
  userContextId,
  linkHandler,
  initialBrowsingContextGroupId: extension.policy.browsingContextGroupId,
  triggeringPrincipal: extension.principal,
};

if (!tabProperties) {
  tabProperties = {};
} else if (typeof tabProperties == "string") {
  tabProperties = { url: tabProperties };
}

try {
  const nativeButtonProperties = getNativeButtonProperties({
    extension,
    buttonProperties,
  });
  const nativeTabProperties = getNativeTabProperties({
    extension,
    tabProperties,
  });
